function saveDB(){
  if(isDemoMode){
    // Demo mode — only update in-memory, no localStorage, no Sheets sync
    updateDashboard();
    return;
  }
  saveUserDB();
  updateDashboard();
  if(isTokenValid()){
    syncToSheets().catch(function(e){console.warn('Sheets sync:',e.message);});
  }
}
function genId(){return Date.now().toString(36)+Math.random().toString(36).slice(2,6);}

// ── NAV ──
var lastSheetRefresh = 0;
async function refreshFromSheetsIfStale(){
  if(isDemoMode) return; // demo mode — no sheets
  // Refresh from Sheets if more than 20 seconds since last refresh — keeps multi-user data fresh
  if(!isTokenValid() || !DB.config.googleSheetId) return;
  var now = Date.now();
  if(now - lastSheetRefresh < 20000) return; // throttle
  lastSheetRefresh = now;
  try{
    await loadFromSheets(true); // silent=true, no toast
  }catch(e){ console.warn('Auto-refresh failed:',e.message); }
}

function showPage(name){
  document.querySelectorAll('.page').forEach(function(p){p.classList.remove('active');});
  document.querySelectorAll('.nav-item').forEach(function(n){n.classList.remove('active');});
  document.querySelectorAll('.bottom-nav-item').forEach(function(n){n.classList.remove('active');});
  var pg=document.getElementById('page-'+name);
  if(pg)pg.classList.add('active');
  var nav=document.getElementById('nav-'+name);
  if(nav)nav.classList.add('active');
  var bnav=document.getElementById('bnav-'+name);
  if(bnav)bnav.classList.add('active');

  var refreshPages = ['dashboard','vendors','history','payment'];
  if(refreshPages.indexOf(name)!==-1){
    refreshFromSheetsIfStale().then(function(){
      if(name==='vendors')renderVendors();
      if(name==='history')renderHistory();
      if(name==='payment')initPaymentPage();
      if(name==='dashboard')updateDashboard();
    });
  }

  if(name==='vendors')renderVendors();
  if(name==='history')renderHistory();
  if(name==='payment')initPaymentPage();
  if(name==='config')initConfigPage();
  if(name==='dashboard')updateDashboard();
  if(name==='assistant')initAssistantPage();
}

function showConfigTab(tab,el){
  document.querySelectorAll('.config-tab').forEach(function(t){t.classList.remove('active');});
  document.querySelectorAll('.config-panel').forEach(function(p){p.classList.remove('active');});
  document.getElementById('config-'+tab).classList.add('active');
  el.classList.add('active');
}

// ── TOAST ──
function toast(msg,type){
  type=type||'info';
  var wrap=document.getElementById('toastWrap');
  var el=document.createElement('div');
  el.className='toast '+type;
  var icons={success:'✅',error:'❌',info:'ℹ️'};
  el.innerHTML='<span>'+(icons[type]||'ℹ️')+'</span><span>'+msg+'</span>';
  el.style.animation='slideIn 0.2s ease';
  wrap.appendChild(el);
  setTimeout(function(){el.remove();},3500);
}

