// ── AUTH & GOOGLE SHEETS ──
var NETLIFY_URL = 'https://rtgs-payment-manager.netlify.app';
var currentUser = null; // { name, email, picture, accessToken, tokenExpiry }

// ── YOUR GOOGLE OAUTH CLIENT ID ──
var GOOGLE_CLIENT_ID = 'YOUR CLIENT ID'; // Replace with your Client ID

function startGoogleLogin(){
  if(!GOOGLE_CLIENT_ID || GOOGLE_CLIENT_ID === 'YOUR_CLIENT_ID_HERE'){
    document.getElementById('loginStatus').innerHTML = '<span style="color:var(--danger)">❌ Client ID not configured in app.js</span>';
    return;
  }
  launchOAuth(GOOGLE_CLIENT_ID);
}


function launchOAuth(clientId){
  var loginStatus = document.getElementById('loginStatus');
  loginStatus.innerHTML = '⏳ Opening Google login...';
  var scope = encodeURIComponent('https://www.googleapis.com/auth/spreadsheets https://www.googleapis.com/auth/drive.file https://www.googleapis.com/auth/userinfo.profile https://www.googleapis.com/auth/userinfo.email');
  var redirectUri = encodeURIComponent(NETLIFY_URL);
  var authUrl = 'https://accounts.google.com/o/oauth2/v2/auth'
    +'?client_id='+encodeURIComponent(clientId)
    +'&redirect_uri='+redirectUri
    +'&response_type=token'
    +'&scope='+scope
    +'&prompt=consent';
  window.location.href = authUrl;
}

function handleOAuthRedirect(){
  var hash = window.location.hash;
  if(!hash || !hash.includes('access_token=')) return false;
  var params = {};
  hash.slice(1).split('&').forEach(function(p){
    var kv = p.split('=');
    params[decodeURIComponent(kv[0])] = decodeURIComponent(kv[1]||'');
  });
  if(!params.access_token) return false;
  // Clean URL immediately
  history.replaceState(null,'',window.location.pathname);
  // Store token temporarily and fetch user info
  var token = params.access_token;
  var expiresIn = parseInt(params.expires_in||3600);
  fetchUserInfo(token, expiresIn);
  return true;
}

async function fetchUserInfo(token, expiresIn){
  showLoginScreen();
  document.getElementById('loginStatus').textContent = '⏳ Signing in...';
  try{
    var resp = await fetch('https://www.googleapis.com/oauth2/v2/userinfo', {
      headers:{'Authorization':'Bearer '+token}
    });
    var info = await resp.json();
    if(info.error) throw new Error(info.error.message);
    currentUser = {
      name: info.name||info.email,
      email: info.email,
      picture: info.picture||'',
      accessToken: token,
      tokenExpiry: Date.now() + (expiresIn*1000)
    };
    // Load user-specific DB from localStorage key
    loadUserDB();
    // Then load from sheets if available
    onLoginSuccess();
  }catch(e){
    document.getElementById('loginStatus').textContent = '❌ Sign in failed: '+e.message;
  }
}

function isTokenValid(){
  return !!(currentUser && currentUser.accessToken && Date.now() < currentUser.tokenExpiry);
}

function loadUserDB(){
  // Each user gets their own localStorage key based on email
  var key = 'rtgs_db_'+btoa(currentUser.email);
  try{
    var s = localStorage.getItem(key);
    if(s){ var p = JSON.parse(s); DB = Object.assign(DB,p); }
  }catch(e){}
  if(!DB.config.fieldMapping) DB.config.fieldMapping = defaultMapping();
  if(!DB.config.googleClientId && localStorage.getItem('rtgs_client_id')){
    DB.config.googleClientId = localStorage.getItem('rtgs_client_id');
  }
}

function saveUserDB(){
  if(!currentUser) return;
  var key = 'rtgs_db_'+btoa(currentUser.email);
  try{ localStorage.setItem(key, JSON.stringify(DB)); }catch(e){}
  // Save client ID globally so it persists across logins
  if(DB.config.googleClientId) localStorage.setItem('rtgs_client_id', DB.config.googleClientId);
}

async function onLoginSuccess(){
  // Save session to localStorage for page refresh persistence
  try{
    localStorage.setItem('rtgs_session', JSON.stringify({
      name: currentUser.name,
      email: currentUser.email,
      picture: currentUser.picture,
      accessToken: currentUser.accessToken,
      tokenExpiry: currentUser.tokenExpiry
    }));
  }catch(e){}

  // Update sidebar user info
  document.getElementById('userName').textContent = currentUser.name;
  document.getElementById('userEmail').textContent = currentUser.email;
  if(currentUser.picture){
    var av = document.getElementById('userAvatar');
    av.src = currentUser.picture;
    av.style.display = 'block';
  }

  // First-time login (no sheet linked yet) — ask for invite code
  if(!DB.config.googleSheetId){
    showInviteCodePrompt();
    return;
  }

  // Returning user — load their existing sheet
  hideLoginScreen();
  updateDashboard();
  document.getElementById('loginStatus').textContent = '';
  toast('Loading your data from Google Sheets...','info');
  await loadFromSheets();
}

function showInviteCodePrompt(){
  var loginStatus = document.getElementById('loginStatus');
  loginStatus.innerHTML = '';

  var wrap = document.createElement('div');
  wrap.style.cssText = 'text-align:left;margin-top:12px;';

  var title = document.createElement('div');
  title.style.cssText = 'font-size:13px;font-weight:600;margin-bottom:8px;color:var(--text);';
  title.textContent = 'Joining a team?';

  var sub = document.createElement('div');
  sub.style.cssText = 'font-size:12px;color:var(--text2);margin-bottom:10px;';
  sub.textContent = 'Enter your team\'s invite code to access shared vendor data, or skip to create your own workspace.';

  var input = document.createElement('input');
  input.type = 'text';
  input.id = 'inviteCodeInput';
  input.placeholder = 'Enter invite code (optional)';
  input.style.cssText = 'width:100%;padding:9px 12px;background:var(--surface2);border:1px solid var(--border);border-radius:8px;color:var(--text);font-size:13px;outline:none;margin-bottom:10px;box-sizing:border-box;font-family:DM Mono,monospace;';

  var joinBtn = document.createElement('button');
  joinBtn.textContent = 'Join Team';
  joinBtn.style.cssText = 'width:100%;padding:10px;background:var(--accent);border:none;border-radius:8px;color:#fff;font-size:13px;font-weight:600;cursor:pointer;font-family:DM Sans,sans-serif;margin-bottom:8px;';
  joinBtn.onclick = submitInviteCode;

  var skipBtn = document.createElement('button');
  skipBtn.textContent = 'Skip — Create My Own Workspace';
  skipBtn.style.cssText = 'width:100%;padding:10px;background:transparent;border:1px solid var(--border);border-radius:8px;color:var(--text2);font-size:13px;font-weight:500;cursor:pointer;font-family:DM Sans,sans-serif;';
  skipBtn.onclick = skipInviteCode;

  wrap.appendChild(title);
  wrap.appendChild(sub);
  wrap.appendChild(input);
  wrap.appendChild(joinBtn);
  wrap.appendChild(skipBtn);
  loginStatus.appendChild(wrap);
  setTimeout(function(){input.focus();},200);
}

async function submitInviteCode(){
  var input = document.getElementById('inviteCodeInput');
  var code = input ? input.value.trim() : '';
  if(!code){ toast('Enter a code or click Skip','error'); return; }

  document.getElementById('loginStatus').innerHTML = '⏳ Joining team...';
  // Invite code IS the Sheet ID — try to access it
  DB.config.googleSheetId = code;
  try{
    // Verify access by trying to read the sheet
    await gFetch('https://sheets.googleapis.com/v4/spreadsheets/'+code+'?fields=spreadsheetId');
    saveUserDB();
    hideLoginScreen();
    updateDashboard();
    toast('Joined team workspace!','success');
    await loadFromSheets();
  }catch(e){
    DB.config.googleSheetId = '';
    document.getElementById('loginStatus').innerHTML = '<span style="color:var(--danger)">❌ '+e.message+'</span><br><span style="font-size:11px;color:var(--text3);">Ask the team owner to share their Sheet with '+currentUser.email+' (Editor access), and add this email as a Test User in Google Cloud Console.</span>';
    // Re-show the prompt below the error
    setTimeout(function(){
      var existing = document.getElementById('inviteCodeInput');
      if(!existing) showInviteCodePrompt();
    }, 100);
  }
}

async function skipInviteCode(){
  document.getElementById('loginStatus').innerHTML = '⏳ Setting up your workspace...';
  await initGoogleSheets();
  hideLoginScreen();
  updateDashboard();
  toast('Welcome! Your workspace is ready.','success');
}

function signOut(){
  if(!confirm('Sign out?')) return;
  localStorage.removeItem('rtgs_session');
  chatHistory = [];
  currentUser = null;
  DB = {vendors:[],accounts:[],banks:[],transactions:[],config:{
    ocrEnabled:false,anthropicApiKey:'',googleEnabled:false,
    googleEmail:'',googleClientId:DB.config.googleClientId||'',
    googleSheetId:'',fieldMapping:defaultMapping(),
    defaultAccountId:null,defaultBankId:null
  }};
  showLoginScreen();
  toast('Signed out','info');
}

function showLoginScreen(){
  document.getElementById('loginScreen').style.display = 'flex';
  document.getElementById('appLayout').style.display = 'none';
}

function hideLoginScreen(){
  document.getElementById('loginScreen').style.display = 'none';
  document.getElementById('appLayout').style.display = 'flex';
}

async function gFetch(url, opts){
  if(!isTokenValid()) throw new Error('Session expired — please sign in again');
  opts = opts||{};
  opts.headers = Object.assign({
    'Authorization':'Bearer '+currentUser.accessToken,
    'Content-Type':'application/json'
  }, opts.headers||{});
  var resp = await fetch(url, opts);
  if(!resp.ok){ var err=await resp.text(); throw new Error(resp.status+' '+err.slice(0,120)); }
  return resp.json();
}

async function initGoogleSheets(){
  if(!isTokenValid()) return;
  var data = await gFetch('https://sheets.googleapis.com/v4/spreadsheets',{
    method:'POST',
    body:JSON.stringify({
      properties:{title:'RTGS - '+currentUser.email},
      sheets:[
        {properties:{title:'Vendors',sheetId:0}},
        {properties:{title:'MyAccounts',sheetId:1}},
        {properties:{title:'Transactions',sheetId:2}},
        {properties:{title:'Banks',sheetId:3}},
      ]
    })
  });
  DB.config.googleSheetId = data.spreadsheetId;
  saveUserDB();
  await syncToSheets();
}

async function ensureBanksSheetExists(){
  var sid = DB.config.googleSheetId;
  try{
    await gFetch('https://sheets.googleapis.com/v4/spreadsheets/'+sid+'/values/Banks!A1');
  }catch(e){
    // Banks sheet doesn't exist — add it
    try{
      await gFetch('https://sheets.googleapis.com/v4/spreadsheets/'+sid+':batchUpdate',{
        method:'POST',
        body:JSON.stringify({requests:[{addSheet:{properties:{title:'Banks'}}}]})
      });
    }catch(e2){ console.warn('Could not create Banks sheet:',e2.message); }
  }
}

async function syncToSheets(){
  if(!DB.config.googleSheetId||!isTokenValid()) return;
  var sid = DB.config.googleSheetId;
  var base = 'https://sheets.googleapis.com/v4/spreadsheets/'+sid+'/values';
  await ensureBanksSheetExists();
  var vRows = [['ID','Name','Account','IFSC','Bank','Branch','AccType','Mobile','Address','LEI']].concat(
    DB.vendors.map(function(v){return[v.id,v.name||'',v.account||'',v.ifsc||'',v.bank||'',v.branch||'',v.acctype||'',v.mobile||'',v.address||'',v.lei||''];}));
  var aRows = [['ID','Name','Account','AccType','CustID','Address','Mobile','Email','PAN','LEI','Default']].concat(
    DB.accounts.map(function(a){return[a.id,a.name||'',a.account||'',a.acctype||'',a.custid||'',a.address||'',a.mobile||'',a.email||'',a.pan||'',a.lei||'',(DB.config.defaultAccountId===a.id)?'YES':''];}));
  var tRows = [['ID','Date','VendorID','Vendor','VendorBank','VendorIFSC','VendorAccount','FromAccount','Amount']].concat(
    DB.transactions.map(function(t){return[t.id,t.date||'',t.vendorId||'',t.vendorName||'',t.vendorBank||'',t.vendorIfsc||'',t.vendorAccount||'',t.accountName||'',t.amount||0];}));
  var bRows = [['ID','BankName','Branch','IFSC','Address','Default']].concat(
    DB.banks.map(function(b){return[b.id,b.bankname||'',b.branch||'',b.ifsc||'',b.address||'',(DB.config.defaultBankId===b.id)?'YES':''];}));
  await gFetch(base+':batchClear',{method:'POST',body:JSON.stringify({ranges:['Vendors!A:Z','MyAccounts!A:Z','Transactions!A:Z','Banks!A:Z']})});
  await gFetch(base+':batchUpdate',{method:'POST',body:JSON.stringify({valueInputOption:'RAW',data:[
    {range:'Vendors!A1',values:vRows},
    {range:'MyAccounts!A1',values:aRows},
    {range:'Transactions!A1',values:tRows},
    {range:'Banks!A1',values:bRows},
  ]})});
}

async function loadFromSheets(silent){
  if(!DB.config.googleSheetId||!isTokenValid()) return;
  var sid = DB.config.googleSheetId;
  var base = 'https://sheets.googleapis.com/v4/spreadsheets/'+sid+'/values';
  try{
    var results = await Promise.all([
      gFetch(base+'/Vendors!A2:J1000'),
      gFetch(base+'/MyAccounts!A2:K1000'),
      gFetch(base+'/Transactions!A2:I1000'),
      gFetch(base+'/Banks!A2:F1000').catch(function(){return {values:null};}), // Banks tab may not exist for older sheets
    ]);
    if(results[0].values&&results[0].values.length)
      DB.vendors=results[0].values.map(function(r){return{id:r[0]||'',name:r[1]||'',account:r[2]||'',ifsc:r[3]||'',bank:r[4]||'',branch:r[5]||'',acctype:r[6]||'CD',mobile:r[7]||'',address:r[8]||'',lei:r[9]||''};});
    if(results[1].values&&results[1].values.length){
      DB.accounts=results[1].values.map(function(r){return{id:r[0]||'',name:r[1]||'',account:r[2]||'',acctype:r[3]||'CD',custid:r[4]||'',address:r[5]||'',mobile:r[6]||'',email:r[7]||'',pan:r[8]||'',lei:r[9]||''};});
      var def=results[1].values.find(function(r){return r[10]==='YES';});
      if(def) DB.config.defaultAccountId=def[0];
    }
    if(results[2].values&&results[2].values.length)
      DB.transactions=results[2].values.map(function(r){
        // Detect old 8-column format (no VendorID) vs new 9-column format
        // New format: r[8] is numeric amount. Old format: r[7] is numeric amount, r[8] is undefined.
        var isOldFormat = (r.length<=8) || (r[8]===undefined || r[8]==='');
        if(isOldFormat){
          return{id:r[0]||'',date:r[1]||'',vendorId:'',vendorName:r[2]||'',vendorBank:r[3]||'',vendorIfsc:r[4]||'',vendorAccount:r[5]||'',accountName:r[6]||'',amount:parseFloat(r[7])||0,timestamp:Date.now()};
        }
        return{id:r[0]||'',date:r[1]||'',vendorId:r[2]||'',vendorName:r[3]||'',vendorBank:r[4]||'',vendorIfsc:r[5]||'',vendorAccount:r[6]||'',accountName:r[7]||'',amount:parseFloat(r[8])||0,timestamp:Date.now()};
      });
    if(results[3].values&&results[3].values.length){
      DB.banks=results[3].values.map(function(r){return{id:r[0]||'',bankname:r[1]||'',branch:r[2]||'',ifsc:r[3]||'',address:r[4]||'',pdfData:null};});
      var defBank=results[3].values.find(function(r){return r[5]==='YES';});
      if(defBank) DB.config.defaultBankId=defBank[0];
    }
    saveUserDB();
    updateDashboard();
    if(!silent) toast('Data loaded from Google Sheets','success');
  }catch(e){
    if(!silent) toast('Could not load from Sheets: '+e.message,'error');
    else throw e;
  }
}

