async function generateRTGSPDF(){
  var fd=getFormData();if(!validateForm(fd))return;
  var btn=document.getElementById('generatePdfBtn');
  btn.innerHTML='<span class="spinner"></span> Generating...';btn.disabled=true;
  try{
    var pdfBytes;
    var bank=DB.banks.find(function(b){return b.id===DB.config.defaultBankId;});
    if(bank&&bank.pdfData){
      var b64=bank.pdfData.split(',')[1];
      pdfBytes=Uint8Array.from(atob(b64),function(c){return c.charCodeAt(0);});
    }else{
      pdfBytes=await loadPDFTemplate();
    }
    var pdfDoc=await PDFLib.PDFDocument.load(pdfBytes);
    var pages=pdfDoc.getPages();var page=pages[0];
    // dt(text, x, y) - x,y are already in PDF points, y from bottom of page
    var helveticaBold = await pdfDoc.embedFont(PDFLib.StandardFonts.HelveticaBold);
    var helveticaRegular = await pdfDoc.embedFont(PDFLib.StandardFonts.Helvetica);

    // Fit text within maxWidth by reducing font size down to minSz
    function fitText(text, x, y, maxWidth, startSz, minSz, font){
      if(!text) return;
      var sz = startSz || 9;
      var min = minSz || 6;
      var f = font || helveticaBold;
      try{
        var w = f.widthOfTextAtSize(String(text), sz);
        while(w > maxWidth && sz > min){
          sz -= 0.5;
          w = f.widthOfTextAtSize(String(text), sz);
        }
        // If still too wide at minimum font, truncate with ellipsis
        var displayText = String(text);
        if(w > maxWidth){
          while(f.widthOfTextAtSize(displayText+'…', sz) > maxWidth && displayText.length > 1){
            displayText = displayText.slice(0,-1);
          }
          displayText = displayText + '…';
        }
        page.drawText(displayText, {x:x, y:y, size:sz, color:PDFLib.rgb(0,0,0), font:f});
      }catch(e){console.warn('fitText failed for',text,e);}
    }

    // dt: bold text, auto-fit to a generous max width (most fields have plenty of space)
    function dt(text,x,y,sz){
      if(!text)return;
      try{page.drawText(String(text),{x:x,y:y,size:sz||9,color:PDFLib.rgb(0,0,0),font:helveticaBold});}
      catch(e){console.warn('drawText failed for',text,e);}
    }
    function dtRegular(text,x,y,sz){
      if(!text)return;
      try{page.drawText(String(text),{x:x,y:y,size:sz||9,color:PDFLib.rgb(0,0,0),font:helveticaRegular});}
      catch(e){console.warn('drawText failed for',text,e);}
    }
    var today=fd.today;var amt=fd.amount;
    var words=numToWords(amt).replace('Rupees ','');
    // Coordinates: drawText(text, x, y) where y is from BOTTOM of page (pdf-lib standard)
    // All coords derived precisely from PDF structure extraction
    dt(today,              480,  706.3);
    // Branch field: ~70pts available (underscores end ~x130, text starts x58)
    fitText(fd.bank?fd.bank.branch:'', 58, 678.2, 70, 9, 6);
    dt(amt.toLocaleString('en-IN'), 168, 641.7);
    // Amount words - shrink font to fit on one line, only wrap if extremely long
    if(words.length>78){
      dt(words.substring(0,78), 318, 644.5, 6.5);
      dt(words.substring(78),   318, 636.5, 6.5);
    } else if(words.length>62){
      dt(words, 318, 641.7, 6.5);
    } else {
      dt(words, 318, 641.7, 8);
    }
    // Cash/Cheque marking removed per request — checkboxes left blank
    // if(fd.isCash)dt('X',   68, 615.5, 9);
    // if(fd.isCheque)dt('X', 108, 615.5, 9);
    // APPLICANT details — +6pt gap after label
    fitText(fd.account.name, 94, 580.7, 205, 9, 6);
    dt(fd.account.account, 118, 569.2, 9);
    dt(fd.account.acctype, 196, 557.6, 9);
    dt(fd.account.custid,  133, 546.4, 9);
    fitText(fd.account.address, 101, 534.9, 200, 8, 6);
    dt(fd.account.mobile,  126, 511.8, 9);
    fitText(fd.account.email, 100, 500.3, 200, 8, 6);
    dt(fd.account.pan,     128, 488.7, 9);
    if(fd.account.lei)dt(fd.account.lei, 64, 477.2, 8);
    // BENEFICIARY details — +6pt gap after label
    dt(fd.vendor.ifsc,     371, 580.7, 9);
    fitText(fd.vendor.bank, 353, 569.2, 225, 9, 6);
    fitText(fd.vendor.branch, 364, 557.6, 214, 9, 6);
    dt(fd.vendor.account,  405, 546.4, 9);
    dt(fd.vendor.account, 437, 534.9, 9);  // repeat account value — bold (matches other filled fields)
    dt(fd.vendor.acctype,  433, 523.3, 9);
    fitText(fd.vendor.name, 358, 511.8, 220, 9, 6);
    dt(fd.vendor.mobile,   412, 500.3, 9);
    if(fd.vendor.lei)dt(fd.vendor.lei, 329, 454.9, 8);
    var out=await pdfDoc.save();
    // Convert to base64 and use data URI to avoid blob URL CSP issues
    var filename = 'RTGS_'+fd.vendor.name.replace(/\s+/g,'_')+'_'+today.replace(/\//g,'-')+'.pdf';
    var blob = new Blob([out], {type:'application/pdf'});

    // Try Blob URL first (works on mobile browsers on Netlify)
    if(window.URL && window.URL.createObjectURL){
      var url = URL.createObjectURL(blob);
      var a = document.createElement('a');
      a.href = url;
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      setTimeout(function(){ URL.revokeObjectURL(url); document.body.removeChild(a); }, 1000);
    } else {
      // Fallback: data URI (for environments that block blob URLs)
      var reader = new FileReader();
      reader.onload = function(e){
        var a = document.createElement('a');
        a.href = e.target.result;
        a.download = filename;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
      };
      reader.readAsDataURL(blob);
    }
    if(isReprintMode){ isReprintMode=false; }
    if(isDemoMode){
      toast('PDF downloaded! (Demo mode)','info');
    } else {
      toast('PDF downloaded!','success');
    }
  }catch(e){toast('PDF error: '+e.message,'error');console.error(e);}
  finally{btn.innerHTML='📥 Download PDF';btn.disabled=false;}
}

