// ── CHAT MESSAGE RENDERING ──
function addChatMessage(role, html, id){
  var container = document.getElementById('chatMessages');
  if(!container) return;
  var msg = document.createElement('div');
  msg.className = 'chat-msg ' + role;
  if(id) msg.id = id;
  if(role === 'assistant'){
    msg.innerHTML = '<div class="chat-avatar">🤖</div><div class="chat-bubble">'+html+'</div>';
  } else {
    msg.innerHTML = '<div class="chat-bubble">'+html+'</div>';
  }
  container.appendChild(msg);
  container.scrollTop = container.scrollHeight;
  return msg;
}

function updateChatMessage(id, html){
  var msg = document.getElementById(id);
  if(!msg) return;
  var bubble = msg.querySelector('.chat-bubble');
  if(bubble) bubble.innerHTML = html;
  var container = document.getElementById('chatMessages');
  if(container) container.scrollTop = container.scrollHeight;
}

// ── SEND MESSAGE ──
async function sendAssistantMessage(){
  var inp = document.getElementById('chatInput');
  var text = inp ? inp.value.trim() : '';
  if(!text) return;

  // In demo mode without API key — use simulated response
  var useSimulation = isDemoMode && !DB.config.anthropicApiKey;

  if(!useSimulation && !DB.config.anthropicApiKey){
    toast('Add your Anthropic API key in Agent Configuration','error');
    return;
  }

  inp.value = '';
  addChatMessage('user', escHtml(text));
  chatHistory.push({role:'user', content: text});

  var loadingId = 'loading-' + Date.now();
  addChatMessage('assistant', '<span style="color:var(--text3)">Thinking...</span>', loadingId);

  try{
    var response = useSimulation
      ? simulateAssistantResponse(text)
      : await callAssistantAPI(text);
    updateChatMessage(loadingId, response.html);
    // Store plain text of response in history (strip HTML tags)
    var plainResp = response.html.replace(/<[^>]+>/g,'');
    chatHistory.push({role:'assistant', content: plainResp});
    // Keep last 10 exchanges to avoid token bloat
    if(chatHistory.length > 20) chatHistory = chatHistory.slice(-20);
    if(response.intent && response.intent.type === 'payment'){
      handlePaymentIntent(loadingId, response.intent);
    }
  }catch(e){
    updateChatMessage(loadingId, '❌ Error: ' + escHtml(e.message));
  }
}

// Simulated AI response for demo mode (no API key needed)
function simulateAssistantResponse(text){
  var lower = text.toLowerCase();
  // Try to match a vendor from demo data
  var matched = fuzzyMatchForAssistant(text);
  var defaultAcc = DB.accounts.find(function(a){ return a.id===DB.config.defaultAccountId; }) || DB.accounts[0];

  // Extract amount
  var amount = 0;
  var amtMatch = text.match(/[₹Rs\.]*\s*([\d,]+(?:\.\d+)?)\s*(?:thousand|lakh|crore)?/i);
  if(amtMatch){
    var num = parseFloat(amtMatch[1].replace(/,/g,''));
    var lwr = text.toLowerCase();
    if(lwr.includes('lakh')) num *= 100000;
    else if(lwr.includes('thousand')) num *= 1000;
    else if(lwr.includes('crore')) num *= 10000000;
    amount = num;
  }

  if((lower.includes('payment') || lower.includes('pay') || lower.includes('transfer')) && matched.length > 0){
    var v = matched[0];
    return {
      html: 'I found <strong>'+escHtml(v.name)+'</strong> in your vendor master. Here are the payment details:',
      intent: {
        type: 'payment',
        vendorId: v.id,
        vendorName: v.name,
        amount: amount || 50000,
        accountId: defaultAcc ? defaultAcc.id : ''
      }
    };
  }
  if(lower.includes('vendor') || lower.includes('find') || lower.includes('search')){
    if(matched.length > 0){
      return {
        html: 'Found '+matched.length+' matching vendor(s): '+matched.map(function(v){ return '<strong>'+escHtml(v.name)+'</strong>'; }).join(', ')+'. Want to create a payment for any of these?',
        intent: null
      };
    }
    return { html: 'No vendors found matching your query. Try a different name or add a new vendor.', intent: null };
  }
  if(lower.includes('history') || lower.includes('transaction') || lower.includes('last')){
    var recent = DB.transactions.slice(-3).reverse();
    if(recent.length === 0) return { html: 'No transactions found yet.', intent: null };
    var list = recent.map(function(t){ return '• '+t.vendorName+' — ₹'+parseFloat(t.amount).toLocaleString('en-IN')+' on '+t.date; }).join('<br>');
    return { html: 'Recent transactions:<br>'+list, intent: null };
  }
  return {
    html: '🎯 <strong>Demo Mode</strong> — I can simulate payment creation! Try saying:<br>• "Create payment for Alpha Construction of ₹50,000"<br>• "Find vendor Bharat Steel"<br>• "Show recent transactions"',
    intent: null
  };
}

function escHtml(s){
  return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}

// ── AI API CALL ──
async function callAssistantAPI(userMessage){
  // Fuzzy-match vendor from user message first
  var topVendors = fuzzyMatchForAssistant(userMessage);

  // Build context
  var vendorContext = topVendors.length > 0
    ? 'Matching vendors:\n' + topVendors.map(function(v){
        return '- '+v.name+' | Bank: '+v.bank+' | IFSC: '+v.ifsc+' | A/C: '+v.account;
      }).join('\n')
    : 'No matching vendors found in the system.';

  var accountContext = DB.accounts.length > 0
    ? 'Sender accounts:\n' + DB.accounts.map(function(a){
        return '- '+a.name+' | A/C: '+a.account+(DB.config.defaultAccountId===a.id?' [DEFAULT]':'');
      }).join('\n')
    : 'No sender accounts configured.';

  var systemPrompt = 'You are an RTGS payment assistant for an Indian business. '
    + 'Help users create bank payments by extracting vendor, amount, and account details from their message.\n\n'
    + accountContext + '\n\n' + vendorContext + '\n\n'
    + 'RULES:\n'
    + '1. If user wants to create a payment, extract: vendor name, amount (in INR), and which sender account to use (default if not specified).\n'
    + '2. If a matching vendor is found, confirm details before proceeding.\n'
    + '3. If no vendor match found, say so and suggest adding the vendor.\n'
    + '4. For amounts, understand Indian number formats: "50 thousand"=50000, "2 lakh"=200000, "1.5 lakh"=150000.\n'
    + '5. Respond in the same language the user used (English or Hindi).\n'
    + '6. Keep responses short and conversational.\n'
    + '7. If user says "yes", "ok", "confirm", "haan", "theek hai" — they are confirming the PREVIOUS payment. Return the same intent again.\n'
    + '8. If user says "no", "cancel", "nahi" — they are cancelling. Return intent:null.\n'
    + '9. CRITICAL: Respond ONLY with a single valid JSON object. No text before or after it. No markdown. No code blocks.\n'
    + 'Format: {"message":"plain text only, no ** or * or backticks","intent":{"type":"payment","vendorId":"...","vendorName":"...","amount":50000,"accountId":"..."}}\n'
    + 'If no payment intent: {"message":"your response","intent":null}\n'
    + 'The message field must contain ONLY plain readable text. Never include JSON, markdown bold (**), or code blocks in the message field.';

  // Build messages array with history for context
  var messages = chatHistory.slice(-10); // last 5 exchanges
  // Ensure last message is current user input
  if(!messages.length || messages[messages.length-1].role !== 'user'){
    messages.push({role:'user', content: userMessage});
  }

  var resp = await fetch('https://api.anthropic.com/v1/messages', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'x-api-key': DB.config.anthropicApiKey,
      'anthropic-version': '2023-06-01',
      'anthropic-dangerous-direct-browser-access': 'true'
    },
    body: JSON.stringify({
      model: 'claude-haiku-4-5-20251001',
      max_tokens: 500,
      messages: messages,
      system: systemPrompt
    })
  });

  if(!resp.ok){ var err=await resp.text(); throw new Error(resp.status+' '+err.slice(0,100)); }
  var data = await resp.json();
  var raw = data.content && data.content[0] ? data.content[0].text : '{}';

  var parsed = {};
  var cleaned = raw.replace(/```json[\s\S]*?```/g,'').replace(/```[\s\S]*?```/g,'').trim();
  // Try to extract JSON from anywhere in the response
  var jsonMatch = raw.match(/\{[\s\S]*"message"[\s\S]*\}/);
  if(jsonMatch){
    try{ parsed = JSON.parse(jsonMatch[0]); }catch(e){}
  }
  if(!parsed.message){
    try{ parsed = JSON.parse(cleaned); }catch(e){ parsed = {message: cleaned, intent: null}; }
  }
  // Clean the message: strip markdown bold (**text**), strip any remaining JSON
  var msg = parsed.message || cleaned;
  msg = msg.replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>'); // **bold** → <strong>
  msg = msg.replace(/\*(.*?)\*/g,'$1');   // *italic* → plain
  msg = msg.replace(/`([^`]+)`/g,'<code>$1</code>'); // `code` → code
  // Remove any trailing JSON blocks that leaked into message
  msg = msg.replace(/\{[\s\S]*"intent"[\s\S]*\}/g,'').trim();
  msg = msg.replace(/```[\s\S]*?```/g,'').trim();

  return {
    html: msg,
    intent: parsed.intent || null
  };
}

// ── FUZZY MATCH FOR ASSISTANT ──
function fuzzyMatchForAssistant(text){
  var words = text.toLowerCase().split(/\s+/);
  return DB.vendors.map(function(v){
    var name = (v.name||'').toLowerCase();
    var score = 0;
    words.forEach(function(w){
      if(w.length > 2 && name.includes(w)) score += w.length;
    });
    return {vendor:v, score:score};
  }).filter(function(m){ return m.score > 0; })
    .sort(function(a,b){ return b.score-a.score; })
    .slice(0,5)
    .map(function(m){ return m.vendor; });
}

// ── HANDLE PAYMENT INTENT ──
function handlePaymentIntent(msgId, intent){
  if(!intent || intent.type !== 'payment') return;

  var vendor = DB.vendors.find(function(v){ return v.id === intent.vendorId; });
  if(!vendor && intent.vendorName){
    vendor = DB.vendors.find(function(v){ return v.name.toLowerCase() === intent.vendorName.toLowerCase(); });
    if(!vendor){ var fm = fuzzyMatchForAssistant(intent.vendorName); if(fm.length) vendor = fm[0]; }
  }
  var account = DB.accounts.find(function(a){ return a.id === intent.accountId; })
    || DB.accounts.find(function(a){ return a.id === DB.config.defaultAccountId; });

  var msgEl = document.getElementById(msgId);
  var currentHtml = msgEl ? msgEl.querySelector('.chat-bubble').innerHTML : '';

  if(!vendor){
    updateChatMessage(msgId, currentHtml
      + '<div style="margin-top:10px;display:flex;gap:8px;flex-wrap:wrap;">'
      + '<button class="chat-confirm-btn chat-confirm-yes" onclick="showPage(\'vendors\');openVendorModal();setTimeout(function(){var el=document.getElementById(\'v_name\');if(el)el.value=\''+escHtml(intent.vendorName||'')+'\';},100)">➕ Add New Vendor</button>'
      + '<button class="chat-confirm-btn chat-confirm-no" onclick="updateChatMessage(\''+msgId+'\',\'Cancelled.\')">✕ Cancel</button>'
      + '</div>');
    return;
  }

  var amt = '₹'+(intent.amount||0).toLocaleString('en-IN');
  updateChatMessage(msgId, currentHtml
    + '<div style="background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:12px;margin-top:10px;font-size:12.5px;line-height:1.8;">'
    + '<div style="font-weight:600;margin-bottom:6px;">📋 Payment Summary</div>'
    + '<div><span style="color:var(--text3)">Vendor:</span> <strong>'+escHtml(vendor.name)+'</strong></div>'
    + '<div><span style="color:var(--text3)">Bank:</span> '+escHtml(vendor.bank||'-')+'</div>'
    + '<div><span style="color:var(--text3)">IFSC:</span> '+escHtml(vendor.ifsc||'-')+'</div>'
    + '<div><span style="color:var(--text3)">Account:</span> '+escHtml(vendor.account||'-')+'</div>'
    + '<div><span style="color:var(--text3)">Amount:</span> <strong style="color:var(--success)">'+amt+'</strong></div>'
    + '<div><span style="color:var(--text3)">From:</span> '+escHtml(account?account.name:'-')+'</div>'
    + '</div>'
    + '<div style="margin-top:10px;display:flex;gap:8px;flex-wrap:wrap;">'
    + '<button class="chat-confirm-btn chat-confirm-yes" onclick="confirmPaymentFromAssistant(\''+vendor.id+'\',\''+(account?account.id:'')+'\','+intent.amount+',\''+msgId+'\')">✅ Create Payment</button>'
    + '<button class="chat-confirm-btn chat-confirm-no" onclick="updateChatMessage(\''+msgId+'\',\'Cancelled. Let me know if you need anything else.\')">✕ Cancel</button>'
    + '</div>');
}

// ── CONFIRM PAYMENT FROM ASSISTANT ──
function confirmPaymentFromAssistant(vendorId, accountId, amount, msgId){
  updateChatMessage(msgId, '✅ Opening Payment page with details pre-filled...');
  // Set flag BEFORE showPage so initPaymentPage skips clearing
  fromAssistant = true;
  showPage('payment');
  // Pre-fill after page renders
  setTimeout(function(){
    fromAssistant = false;
    var vendor = DB.vendors.find(function(v){ return v.id===vendorId; });
    if(vendor){
      document.getElementById('paymentVendor').value = vendorId;
      document.getElementById('vendorSearchInput').value = vendor.name;
      onVendorSelect();
    }
    // Populate account dropdown first
    var aSel = document.getElementById('paymentAccount');
    aSel.innerHTML = '<option value="">-- Select Account --</option>' +
      DB.accounts.map(function(a){return'<option value="'+a.id+'"'+(DB.config.defaultAccountId===a.id?' selected':'')+'>'+a.name+' ('+a.account+')</option>';}).join('');
    if(accountId) aSel.value = accountId;
    else if(DB.config.defaultAccountId) aSel.value = DB.config.defaultAccountId;
    document.getElementById('paymentAmount').value = amount;
    onAmountChange();
    previewRTGS();
    toast('Payment pre-filled from AI Assistant','success');
  }, 100);
}
